/**
 * API Endpoint Node for Node-RED
 * HTTP endpoint with Zod schema validation and OpenAPI registration
 */

module.exports = function(RED) {
    "use strict";
    var express = require("express");
    var path = require("path");
    var fs = require("fs-extra");

    // Global OpenAPI registry
    if (!RED.settings.openApiRegistry) {
        RED.settings.openApiRegistry = {
            endpoints: new Map(),
            schemas: new Map()
        };
    }

    function APIEndpointNode(n) {
        RED.nodes.createNode(this, n);
        var node = this;
        
        node.method = (n.method || "get").toLowerCase();
        node.url = n.url;
        node.schemaFile = n.schemaFile;
        node.inputSchemaName = n.inputSchemaName;
        node.outputSchemaName = n.outputSchemaName;
        node.description = n.description || "";
        node.tags = n.tags ? n.tags.split(',').map(t => t.trim()) : [];
        
        var schemas = null;
        var pendingRequests = new Map(); // Track pending HTTP requests

        // Load schemas from userDir
        this.loadSchemas = function() {
            if (!node.schemaFile || (!node.inputSchemaName && !node.outputSchemaName)) {
                node.status({fill: "yellow", shape: "ring", text: "no schemas configured"});
                return Promise.resolve(null);
            }

            try {
                node.status({fill: "blue", shape: "dot", text: "loading schemas..."});
                
                const schemaModule = node.requireUserDir(node.schemaFile.replace('@userDir/', ''));
                const loadedSchemas = {};

                // Load input schema
                if (node.inputSchemaName) {
                    if (!schemaModule[node.inputSchemaName]) {
                        throw new Error(`Input schema '${node.inputSchemaName}' not found in ${node.schemaFile}`);
                    }
                    loadedSchemas.inputSchema = schemaModule[node.inputSchemaName];
                }

                // Load output schema  
                if (node.outputSchemaName) {
                    if (!schemaModule[node.outputSchemaName]) {
                        throw new Error(`Output schema '${node.outputSchemaName}' not found in ${node.schemaFile}`);
                    }
                    loadedSchemas.outputSchema = schemaModule[node.outputSchemaName];
                }

                node.status({fill: "green", shape: "dot", text: "schemas loaded"});
                return Promise.resolve(loadedSchemas);

            } catch (error) {
                node.error(`Schema loading failed: ${error.message}`);
                node.status({fill: "red", shape: "ring", text: `schema error`});
                return Promise.reject(error);
            }
        };

        // Same requireUserDir function from TypeScript node
        this.requireUserDir = function(modulePath) {
            const userDir = RED.settings.userDir || process.env.NODE_RED_HOME || '.';
            
            // Try different extensions
            const extensions = ['.js', '.ts', '.tsx', ''];
            let foundPath = null;
            
            for (const ext of extensions) {
                const testPath = path.resolve(userDir, modulePath + ext);
                if (fs.existsSync(testPath)) {
                    foundPath = testPath;
                    break;
                }
            }
            
            if (!foundPath) {
                throw new Error(`Module not found: ${modulePath}`);
            }
            
            try {
                if (foundPath.endsWith('.ts') || foundPath.endsWith('.tsx')) {
                    const tsContent = fs.readFileSync(foundPath, 'utf8');
                    const ts = require('typescript');
                    const result = ts.transpileModule(tsContent, {
                        compilerOptions: {
                            target: ts.ScriptTarget.ES2020,
                            module: ts.ModuleKind.CommonJS,
                            esModuleInterop: true,
                            allowSyntheticDefaultImports: true,
                            skipLibCheck: true
                        }
                    });
                    
                    const Module = require('module');
                    const compiledModule = new Module(foundPath, module);
                    compiledModule.filename = foundPath;
                    compiledModule.paths = Module._nodeModulePaths(path.dirname(foundPath));
                    
                    const compiledRequire = Module.createRequire(foundPath);
                    const compiledFunction = new Function('require', 'module', 'exports', '__filename', '__dirname', result.outputText);
                    compiledFunction.call(
                        compiledModule.exports,
                        compiledRequire,
                        compiledModule,
                        compiledModule.exports,
                        foundPath,
                        path.dirname(foundPath)
                    );
                    
                    return compiledModule.exports;
                } else {
                    if (require.cache[foundPath]) {
                        delete require.cache[foundPath];
                    }
                    return require(foundPath);
                }
            } catch (err) {
                throw new Error(`Failed to require module '${modulePath}': ${err.message}`);
            }
        };

        // Register with OpenAPI registry
        this.registerWithOpenAPI = function() {
            if (!schemas) return;

            const endpointSpec = {
                path: node.url,
                method: node.method.toUpperCase(),
                description: node.description,
                tags: node.tags,
                inputSchema: schemas.inputSchema,
                outputSchema: schemas.outputSchema,
                inputSchemaName: node.inputSchemaName,
                outputSchemaName: node.outputSchemaName,
                nodeId: node.id,
                schemaFile: node.schemaFile
            };

            // Register endpoint
            RED.settings.openApiRegistry.endpoints.set(node.id, endpointSpec);

            // Register schemas if not already registered
            if (node.inputSchemaName && schemas.inputSchema) {
                RED.settings.openApiRegistry.schemas.set(node.inputSchemaName, schemas.inputSchema);
            }
            if (node.outputSchemaName && schemas.outputSchema) {
                RED.settings.openApiRegistry.schemas.set(node.outputSchemaName, schemas.outputSchema);
            }

            node.debug(`Registered API endpoint: ${node.method.toUpperCase()} ${node.url}`);
        };

        // Create HTTP endpoint
        if (node.url) {
            node.httpMiddleware = function(req, res, next) {
                node.emit("input", {
                    _httpReq: req,
                    _httpRes: res,
                    req: req,
                    res: res,
                    payload: req.body || {},
                    params: req.params || {},
                    query: req.query || {},
                    headers: req.headers || {},
                    _msgid: RED.util.generateId()
                });
            };

            var httpMiddleware = function(req, res, next) {
                node.httpMiddleware(req, res, next);
            };

            RED.httpNode[node.method](node.url, httpMiddleware);
            node.status({fill: "green", shape: "dot", text: `${node.method.toUpperCase()} ${node.url}`});
        }

        // Handle incoming HTTP requests
        node.on("input", function(msg, send, done) {
            // Check if this is a response message (has _httpReq and _httpRes from a previous request)
            if (msg._httpReq && msg._httpRes && msg._isResponse) {
                // This is a response coming back - handle HTTP response
                handleHttpResponse(msg);
                if (done) done();
                return;
            }

            // This is a new HTTP request - validate input and forward
            if (schemas && schemas.inputSchema && msg.payload) {
                try {
                    const result = schemas.inputSchema.safeParse(msg.payload);
                    if (!result.success) {
                        const errorDetails = result.error.issues.map(issue => 
                            `${issue.path.join('.')}: ${issue.message}`
                        ).join(', ');
                        
                        node.warn(`Input validation failed: ${errorDetails}`);
                        
                        msg._httpRes.status(400).json({
                            error: 'Input validation failed',
                            details: result.error.issues
                        });
                        if (done) done();
                        return;
                    }
                    msg.payload = result.data;
                } catch (err) {
                    node.error(`Input validation error: ${err.message}`, msg);
                    msg._httpRes.status(500).json({ error: 'Internal validation error' });
                    if (done) done();
                    return;
                }
            }

            // Store the request for later response handling
            if (msg._httpReq && msg._httpRes) {
                pendingRequests.set(msg._msgid, {
                    req: msg._httpReq,
                    res: msg._httpRes,
                    timestamp: Date.now()
                });

                // Clean up old pending requests (older than 30 seconds)
                const now = Date.now();
                for (const [id, request] of pendingRequests.entries()) {
                    if (now - request.timestamp > 30000) {
                        pendingRequests.delete(id);
                    }
                }
            }

            // Forward to business logic
            send(msg);
            if (done) done();
        });

        function handleHttpResponse(msg) {
            const pendingRequest = pendingRequests.get(msg._msgid);
            if (!pendingRequest) {
                node.warn(`No pending request found for message ${msg._msgid}`);
                return;
            }

            const res = pendingRequest.res;
            pendingRequests.delete(msg._msgid);

            // Validate output if schema is configured
            if (schemas && schemas.outputSchema && msg.payload) {
                try {
                    const result = schemas.outputSchema.safeParse(msg.payload);
                    if (!result.success) {
                        const errorDetails = result.error.issues.map(issue => 
                            `${issue.path.join('.')}: ${issue.message}`
                        ).join(', ');
                        
                        node.error(`Output validation failed: ${errorDetails}`);
                        
                        res.status(500).json({
                            error: 'Internal server error',
                            ...(process.env.NODE_ENV === 'development' && { 
                                details: 'Response validation failed: ' + errorDetails
                            })
                        });
                        return;
                    }
                    msg.payload = result.data;
                } catch (err) {
                    node.error(`Output validation error: ${err.message}`, msg);
                    res.status(500).json({ error: 'Internal server error' });
                    return;
                }
            }

            // Send HTTP response
            const statusCode = msg.statusCode || 200;
            const headers = msg.headers || {};
            
            // Set headers
            for (const [key, value] of Object.entries(headers)) {
                res.setHeader(key, value);
            }

            res.status(statusCode).json(msg.payload);
        }

        // Load schemas and register with OpenAPI
        this.loadSchemas().then(loadedSchemas => {
            schemas = loadedSchemas;
            if (schemas) {
                node.registerWithOpenAPI();
                node.status({fill: "green", shape: "dot", text: `${node.method.toUpperCase()} ${node.url} (validated)`});
            } else {
                node.status({fill: "green", shape: "dot", text: `${node.method.toUpperCase()} ${node.url} (no validation)`});
            }
        }).catch(error => {
            schemas = null;
            node.status({fill: "red", shape: "ring", text: "schema error"});
        });

        node.on("close", function() {
            // Unregister from OpenAPI registry
            if (RED.settings.openApiRegistry) {
                RED.settings.openApiRegistry.endpoints.delete(node.id);
            }

            // Clean up pending requests
            for (const [id, request] of pendingRequests.entries()) {
                if (request.res && !request.res.headersSent) {
                    request.res.status(503).json({ error: 'Service unavailable' });
                }
            }
            pendingRequests.clear();
        });
    }

    RED.nodes.registerType("api-endpoint", APIEndpointNode);

    // Serve OpenAPI specification
    RED.httpAdmin.get("/openapi/spec", function(req, res) {
        try {
            const registry = RED.settings.openApiRegistry;
            if (!registry) {
                return res.status(404).json({ error: 'OpenAPI registry not found' });
            }

            const spec = generateOpenAPISpec(registry);
            res.json(spec);
        } catch (error) {
            RED.log.error('Error generating OpenAPI spec: ' + error.message);
            res.status(500).json({ error: 'Failed to generate OpenAPI spec' });
        }
    });

    // Serve Swagger UI
    RED.httpAdmin.get("/openapi/ui", function(req, res) {
        const swaggerUI = `
<!DOCTYPE html>
<html>
<head>
    <title>Node-RED API Documentation</title>
    <link rel="stylesheet" type="text/css" href="https://unpkg.com/swagger-ui-dist@4.15.5/swagger-ui.css" />
</head>
<body>
    <div id="swagger-ui"></div>
    <script src="https://unpkg.com/swagger-ui-dist@4.15.5/swagger-ui-bundle.js"></script>
    <script>
        const ui = SwaggerUIBundle({
            url: '/openapi/spec',
            dom_id: '#swagger-ui',
            presets: [
                SwaggerUIBundle.presets.apis,
                SwaggerUIBundle.presets.standalone
            ]
        });
    </script>
</body>
</html>
        `;
        res.send(swaggerUI);
    });

    function generateOpenAPISpec(registry) {
        try {
            // Use zod-to-openapi library for proper conversion
            const { OpenAPIRegistry, OpenApiGeneratorV3 } = require('@asteasolutions/zod-to-openapi');
            const openApiRegistry = new OpenAPIRegistry();
            
            // Track registered schemas to avoid duplicates
            const registeredSchemas = new Set();
            
            // Register all schemas from endpoints
            for (const [nodeId, endpoint] of registry.endpoints.entries()) {
                // Register input schema
                if (endpoint.inputSchema && endpoint.inputSchemaName && !registeredSchemas.has(endpoint.inputSchemaName)) {
                    try {
                        openApiRegistry.register(endpoint.inputSchemaName, endpoint.inputSchema);
                        registeredSchemas.add(endpoint.inputSchemaName);
                    } catch (err) {
                        console.warn(`[API-Endpoint] Failed to register input schema ${endpoint.inputSchemaName}:`, err.message);
                    }
                }
                
                // Register output schema
                if (endpoint.outputSchema && endpoint.outputSchemaName && !registeredSchemas.has(endpoint.outputSchemaName)) {
                    try {
                        openApiRegistry.register(endpoint.outputSchemaName, endpoint.outputSchema);
                        registeredSchemas.add(endpoint.outputSchemaName);
                    } catch (err) {
                        console.warn(`[API-Endpoint] Failed to register output schema ${endpoint.outputSchemaName}:`, err.message);
                    }
                }
            }
            
            // Register common error schemas
            if (!registeredSchemas.has('ErrorResponse')) {
                const { z } = require('zod');
                const ErrorResponse = z.object({
                    error: z.string(),
                    details: z.array(z.any()).optional()
                });
                openApiRegistry.register('ErrorResponse', ErrorResponse);
                registeredSchemas.add('ErrorResponse');
            }
            
            // Build paths object
            const paths = {};
            for (const [nodeId, endpoint] of registry.endpoints.entries()) {
                const pathKey = endpoint.path;
                const method = endpoint.method.toLowerCase();

                if (!paths[pathKey]) {
                    paths[pathKey] = {};
                }

                const operation = {
                    summary: endpoint.description || `${endpoint.method} ${endpoint.path}`,
                    tags: endpoint.tags.length > 0 ? endpoint.tags : undefined,
                    operationId: `${method}_${pathKey.replace(/[^a-zA-Z0-9]/g, '_')}_${nodeId}`,
                    responses: {
                        '400': {
                            description: 'Bad Request',
                            content: {
                                'application/json': {
                                    schema: { $ref: '#/components/schemas/ErrorResponse' }
                                }
                            }
                        },
                        '500': {
                            description: 'Internal Server Error',
                            content: {
                                'application/json': {
                                    schema: { $ref: '#/components/schemas/ErrorResponse' }
                                }
                            }
                        }
                    }
                };

                // Add request body if input schema exists
                if (endpoint.inputSchema && endpoint.inputSchemaName) {
                    operation.requestBody = {
                        required: true,
                        content: {
                            'application/json': {
                                schema: { $ref: `#/components/schemas/${endpoint.inputSchemaName}` }
                            }
                        }
                    };
                }

                // Add response schema if output schema exists
                if (endpoint.outputSchema && endpoint.outputSchemaName) {
                    operation.responses['200'] = {
                        description: 'Success',
                        content: {
                            'application/json': {
                                schema: { $ref: `#/components/schemas/${endpoint.outputSchemaName}` }
                            }
                        }
                    };
                } else {
                    operation.responses['200'] = {
                        description: 'Success'
                    };
                }

                paths[pathKey][method] = operation;
            }
            
            // Generate the complete OpenAPI document
            const generator = new OpenApiGeneratorV3(openApiRegistry.definitions);
            return generator.generateDocument({
                openapi: '3.0.0',
                info: {
                    title: 'Node-RED API',
                    version: '1.0.0',
                    description: 'Auto-generated API documentation from Node-RED flows with Zod schema validation'
                },
                servers: [
                    {
                        url: '/',
                        description: 'Node-RED Server'
                    }
                ],
                paths
            });
            
        } catch (error) {
            console.warn('[API-Endpoint] zod-to-openapi not available, falling back to basic generation:', error.message);
            
            // Fallback to basic OpenAPI generation
            return generateBasicOpenAPISpec(registry);
        }
    }
    
    // Fallback function for basic OpenAPI generation
    function generateBasicOpenAPISpec(registry) {
        const paths = {};
        const schemas = {};

        // Basic Zod to OpenAPI conversion
        function zodToOpenAPISchema(zodSchema, schemaName) {
            if (!zodSchema || !zodSchema._def) {
                return { type: 'object' };
            }

            const def = zodSchema._def;
            
            switch (def.typeName) {
                case 'ZodString':
                    return { type: 'string' };
                case 'ZodNumber':
                    return { type: 'number' };
                case 'ZodBoolean':
                    return { type: 'boolean' };
                case 'ZodArray':
                    return {
                        type: 'array',
                        items: zodToOpenAPISchema(def.type, `${schemaName}Item`)
                    };
                case 'ZodObject':
                    const properties = {};
                    const required = [];
                    
                    if (def.shape) {
                        const shape = def.shape();
                        for (const [key, value] of Object.entries(shape)) {
                            properties[key] = zodToOpenAPISchema(value, `${schemaName}${key}`);
                            if (!value.isOptional || !value.isOptional()) {
                                required.push(key);
                            }
                        }
                    }
                    
                    return {
                        type: 'object',
                        properties,
                        required: required.length > 0 ? required : undefined
                    };
                default:
                    return { type: 'object' };
            }
        }

        // Process each endpoint
        for (const [nodeId, endpoint] of registry.endpoints.entries()) {
            const pathKey = endpoint.path;
            const method = endpoint.method.toLowerCase();

            if (!paths[pathKey]) {
                paths[pathKey] = {};
            }

            const operation = {
                summary: endpoint.description || `${endpoint.method} ${endpoint.path}`,
                tags: endpoint.tags.length > 0 ? endpoint.tags : undefined,
                operationId: `${method}_${pathKey.replace(/[^a-zA-Z0-9]/g, '_')}_${nodeId}`,
                responses: {
                    '200': {
                        description: 'Success'
                    },
                    '400': {
                        description: 'Bad Request',
                        content: {
                            'application/json': {
                                schema: {
                                    type: 'object',
                                    properties: {
                                        error: { type: 'string' },
                                        details: { type: 'array' }
                                    }
                                }
                            }
                        }
                    },
                    '500': {
                        description: 'Internal Server Error',
                        content: {
                            'application/json': {
                                schema: {
                                    type: 'object',
                                    properties: {
                                        error: { type: 'string' }
                                    }
                                }
                            }
                        }
                    }
                }
            };

            // Add request body if input schema exists
            if (endpoint.inputSchema && endpoint.inputSchemaName) {
                const inputSchemaName = endpoint.inputSchemaName;
                schemas[inputSchemaName] = zodToOpenAPISchema(endpoint.inputSchema, inputSchemaName);
                
                operation.requestBody = {
                    required: true,
                    content: {
                        'application/json': {
                            schema: { $ref: `#/components/schemas/${inputSchemaName}` }
                        }
                    }
                };
            }

            // Add response schema if output schema exists
            if (endpoint.outputSchema && endpoint.outputSchemaName) {
                const outputSchemaName = endpoint.outputSchemaName;
                schemas[outputSchemaName] = zodToOpenAPISchema(endpoint.outputSchema, outputSchemaName);
                
                operation.responses['200'] = {
                    description: 'Success',
                    content: {
                        'application/json': {
                            schema: { $ref: `#/components/schemas/${outputSchemaName}` }
                        }
                    }
                };
            }

            paths[pathKey][method] = operation;
        }

        return {
            openapi: '3.0.0',
            info: {
                title: 'Node-RED API',
                version: '1.0.0',
                description: 'Auto-generated API documentation from Node-RED flows'
            },
            paths,
            components: {
                schemas
            }
        };
    }
}; 